import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"47、【困】 坎下兑上","description":"周易尚氏学 - 47、【困】 坎下兑上","frontmatter":{"title":"47、【困】 坎下兑上","description":"周易尚氏学 - 47、【困】 坎下兑上"},"headers":[],"relativePath":"zh/classics/shangshi/052.md","filePath":"zh/classics/shangshi/052.md"}'),s={name:"zh/classics/shangshi/052.md"};function h(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_47、【困】-坎下兑上" tabindex="-1">47、【困】 坎下兑上 <a class="header-anchor" href="#_47、【困】-坎下兑上" aria-label="Permalink to “47、【困】 坎下兑上”">​</a></h1><p>二五刚得中。处险能说。故亨。贞占也。二五为大人。故贞大人吉也。兑口为言。三至上正反兑。所向不同。故有言不信。此其义始见于左传。左传昭五年明夷之谦曰。于人为言。败言为谗。谓谦上震为人为言。下艮为反震。故曰败言。是以正反震为谗。易林承其义。于讼之困云。心与言反。正释此语也。坤之离云。齐鲁争言。离二至五正反兑。故曰争言。争言即不信。离二至五。与困三至上同也。旧解皆误。详焦氏易诂。</p><p>彖曰。困。刚b也。险以说。困而不失其所亨。其唯君子乎。贞大人吉。以刚中也。有言不信。尚口乃穷也。</p><p>坎刚b。三至上刚b。阳陷阴中故困。因而不失其所亨。唯君子能之。君子即大人。若小人即不堪矣。兑为口。三至上正反兑。故曰尚口。尚口乃穷者。言徒尚口说。必有相反而不信者。故穷也。</p><p>象曰。泽无水。困。君子以致命遂志。</p><p>水在泽下。则泽竭矣。故曰无水。巽为命。而兑为反巽。为毁折。故曰致命。坎为志。二人于渊不出。故曰遂志。学易之君子以之。</p><p>初六。臀困于株木。入于幽谷。三岁不觌。 凶。</p><p>初在下。故曰臀。与夬九四同。株木谓坎。言初欲应四。坎陷为阻。故困于株木。株乾也。韩非子守株待兔。而坎为栋。故为株木。坎为幽。坎陷为谷。初在下。故人于幽谷。离伏故不觌。三岁言其久。盖初失位。处坎下。故其象如此。茹敦和以坎为三岁。王昭素谓初至三三爻为三岁。以坎上六证之。茹说是也。</p><h3 id="象曰。入于幽谷。幽不明也" tabindex="-1">象曰。入于幽谷。幽不明也 <a class="header-anchor" href="#象曰。入于幽谷。幽不明也" aria-label="Permalink to “象曰。入于幽谷。幽不明也”">​</a></h3><p>离伏坎夜。故幽不明。</p><p>九二。困于酒食。朱绂方来。利用亨祀。征凶。无咎。</p><p>坎为酒食。需九五需于酒食是也。二居坎中。故困于酒食。巽为绳为级。坎为赤。巽在二前。故日朱龙（左言）方来。言将膺锡命也。博雅绂绶也。朱级贵人所服。以祭宗庙者。故用以亨祀则利也。然五不应故征凶。得中亦无咎。</p><h3 id="象曰。困于酒食。中有庆也。" tabindex="-1">象曰。困于酒食。中有庆也。 <a class="header-anchor" href="#象曰。困于酒食。中有庆也。" aria-label="Permalink to “象曰。困于酒食。中有庆也。”">​</a></h3><p>居阴中。故有庆。</p><p>六三。困于石。据于蒺藜 入于其宫。不见其妻。凶。</p><p>巽为石。坎为蒺藜。三前临巽。故困于石。下据坎。故据于蒺藜。石坚刚不可人。蒺藜刺人。不可践也。巽为人。坎为宫。故人于其官。巽为齐。妻者齐也。故巽为妻。巽为伏。又上无应。故人宫而不见妻也。象而如是。凶可知也。巽石象。宋邵雍用之。后儒怪骇。岂知焦氏易林。同人之小畜云。戴石上山。步跌不前。小畜小巽为石。下乾为山为首。石在首上。故曰戴石。余证尚多。详焦氏易诂卷一。</p><h3 id="象曰。据于蒺藜。乘刚也。入于其宫。不见其妻。不详也。" tabindex="-1">象曰。据于蒺藜。乘刚也。入于其宫。不见其妻。不详也。 <a class="header-anchor" href="#象曰。据于蒺藜。乘刚也。入于其宫。不见其妻。不详也。" aria-label="Permalink to “象曰。据于蒺藜。乘刚也。入于其宫。不见其妻。不详也。”">​</a></h3><p>释文云。蒺藜茨草。虞翻谓为木名似非。释估茨蒺藜。注布地蔓生。有子。三角刺人。诗庸（右邑）风。墙有茨。传茨蒺藜。孔疏蒺有刺。不可践者是也。惟不可践。故以喻乘刚。若为木则不合矣。正义作藜。然尔雅及毛诗传皆作藜。藜藜通用。阮校必谓藜是。似亦无确证。详善也。</p><p>九四。来徐徐。困于金车。吝。有终。</p><p>来应初为二所阻。故曰徐徐。二坎为车。离色黄外坚。故曰金车。困于金车。申来徐徐之故也。仍阴于险。不得应初也。然与初为正应。初吝终合。故曰有终。</p><h3 id="象曰。来徐徐。志在下也。虽不当位。有与也。" tabindex="-1">象曰。来徐徐。志在下也。虽不当位。有与也。 <a class="header-anchor" href="#象曰。来徐徐。志在下也。虽不当位。有与也。" aria-label="Permalink to “象曰。来徐徐。志在下也。虽不当位。有与也。”">​</a></h3><p>坎为志。志在下。言应初。</p><p>九五。劓刖。 困于赤绂。乃徐有说。利用祭祀。</p><p>艮伏鼻不见。故曰劓。兑折震足象毁。故曰别。坎为赤。巽为绂。故曰赤绂。乃二爻坎为不应。故困于赤绂。上遇阴利往。故有说。兑为食。故利用祭祀。</p><h3 id="象曰。劓刖。-志未得也。乃徐有说。以中直也。利用祭祀。受福也。" tabindex="-1">象曰。劓刖。 志未得也。乃徐有说。以中直也。利用祭祀。受福也。 <a class="header-anchor" href="#象曰。劓刖。-志未得也。乃徐有说。以中直也。利用祭祀。受福也。" aria-label="Permalink to “象曰。劓刖。 志未得也。乃徐有说。以中直也。利用祭祀。受福也。”">​</a></h3><p>坎为志。二无应。故志未得。坎五曰受福。兹与之同。传所谓祭则受福也。</p><p>上六。困于葛藟，于臲卼，曰动悔。有悔，征吉。</p><p>巽为葛c 。三至上正反巽。而三不应上。故困于葛cd e ？危险不安之貌。上乘刚。元应。故有是象。兑为口。曰者自警也。言处此d e ？之境。时时以动海有悔自警。动海者言动而应三。三不应故侮。有悔者言下乘阳又有悔也。征吉谓三。言三往四。上得阳应而吉也。此二句向天的解。姑测其义如是。</p><h3 id="象曰。困于葛藟-未当也。动悔有悔-吉行也。" tabindex="-1">象曰。困于葛藟，未当也。动悔有悔，吉行也。 <a class="header-anchor" href="#象曰。困于葛藟-未当也。动悔有悔-吉行也。" aria-label="Permalink to “象曰。困于葛藟，未当也。动悔有悔，吉行也。”">​</a></h3><p>未当者。言上不宜乘阳也。吉行者。三之四上得阳应。故吉也。</p>',30)])])}const b=e(s,[["render",h]]);export{_ as __pageData,b as default};
